package paasio

import (
	"io"
	"sync"
)

// readCounter wraps an io.Reader and reports the total number of bytes
// successfully read along with the total number of Read calls.
//
// The byte total and operation count are updated atomically under a single
// mutex, so ReadCount always returns a consistent snapshot even when Read
// is called concurrently from multiple goroutines.
type readCounter struct {
	io.Reader
	mutex sync.Mutex
	n     int64
	nops  int
}

// writeCounter wraps an io.Writer and reports the total number of bytes
// successfully written along with the total number of Write calls.
//
// Like readCounter, it guarantees that WriteCount returns consistent
// results in the presence of concurrent Write calls.
type writeCounter struct {
	io.Writer
	mutex sync.Mutex
	n     int64
	nops  int
}

// readWriteCounter wraps an io.ReadWriter and reports statistics for both
// reads and writes, satisfying the ReadWriteCounter interface.
type readWriteCounter struct {
	readCounter
	writeCounter
}

func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{Writer: writer}
}

func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{Reader: reader}
}

func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  readCounter{Reader: readwriter},
		writeCounter: writeCounter{Writer: readwriter},
	}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.Reader.Read(p)
	rc.mutex.Lock()
	rc.nops++
	if err == nil {
		rc.n += int64(n)
	}
	rc.mutex.Unlock()
	return n, err
}

func (rc *readCounter) ReadCount() (int64, int) {
	rc.mutex.Lock()
	defer rc.mutex.Unlock()
	return rc.n, rc.nops
}

func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.Writer.Write(p)
	wc.mutex.Lock()
	wc.nops++
	if err == nil {
		wc.n += int64(n)
	}
	wc.mutex.Unlock()
	return n, err
}

func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mutex.Lock()
	defer wc.mutex.Unlock()
	return wc.n, wc.nops
}
